function compareControls(api){
  const make=(tag,attrs={},text)=>{const e=document.createElement(tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;},button=(id,text)=>make('button',{id,type:'button'},text),panel=api.mount('tools');
  const open=button('compare-balls','Compare selected balls'),count=make('p',{id:'compare-count',class:'hint'});panel.append(make('h3',{},'Compare balls'),count,open);
  const dialog=make('dialog',{id:'compare-dialog','data-shade-addon':api.id,'aria-labelledby':'compare-heading'}),shape=make('select',{id:'compare-shape','aria-label':'Comparison surface'});shape.append(make('option',{value:'square'},'Square'),make('option',{value:'triangle'},'Triangle'));
  const canvas=make('canvas',{id:'compare-wheel',width:640,height:640,'aria-label':'Selected balls on one hue wheel and color surface'}),hint=make('p',{id:'compare-focus',class:'hint'}),legend=make('div',{id:'compare-legend'}),table=make('table',{id:'compare-table'}),head=make('thead'),row=make('tr');for(const label of ['Show / color','HEX','H° / S% / L%','ΔH / ΔS / ΔL'])row.append(make('th',{},label));head.append(row);const body=make('tbody');table.append(head,body);const scroll=make('div',{class:'compare-table-scroll'});scroll.append(table);
  const main=make('div',{class:'compare-grid'}),left=make('div');left.append(canvas,hint);main.append(left,legend);const close=button('compare-close','Close');dialog.append(make('h2',{id:'compare-heading'},'Compare selected balls'),make('p',{class:'hint'},'Points use their actual colors. Each ball has a numbered symbol; select a row to bring overlapping points forward. Hue points show hue; the center shows saturation and lightness. Differences are relative to the same region of ball 1.'),shape,main,scroll,close);document.body.append(dialog);api.onCleanup(()=>dialog.remove());let balls=[],hidden=new Set(),selected=null,points=[],guide;
  const sign=n=>(n>0?'+':'')+Number(n.toFixed(1));
  function redraw(){if(!balls.length)return;points=Comparison.draw(canvas,balls,shape.value,hidden,selected,guide);const focus=Comparison.entries(balls).find(p=>p.key===selected)||Comparison.entries(balls)[0];hint.textContent='Background hue: '+focus.ball.name+' / '+focus.name+' · '+Number(focus.color[0].toFixed(1))+'°. Select a color to inspect its hue slice.';for(const tr of body.children)tr.classList.toggle('selected',tr.dataset.key===selected);}
  function fill(){
    legend.replaceChildren();balls.forEach((b,i)=>{const card=make('div',{class:'compare-card'}),image=make('canvas',{width:160,height:140}),title=make('strong',{},(i+1)+' '+['●','■','◆','▲'][i%4]+' '+b.name);R.ballCanvas(image,b);card.append(image,title);legend.append(card);});
    const base=E.resolve(balls[0]);body.replaceChildren(...Comparison.entries(balls).map(p=>{const tr=make('tr',{'data-key':p.key}),cell=make('td'),check=make('input',{type:'checkbox','aria-label':'Show '+p.ball.name+' '+p.name}),focus=button('',p.label+' · '+p.ball.name+' / '+p.name),swatch=make('span',{class:'compare-swatch'});focus.removeAttribute('id');swatch.style.background=E.toHex(p.color);focus.prepend(swatch);check.checked=!hidden.has(p.key);cell.append(check,focus);tr.append(cell,make('td',{},E.toHex(p.color)),make('td',{},p.color.map(n=>Number(n.toFixed(1))).join(' / ')),make('td',{},base[p.id]?Comparison.difference(p.color,base[p.id]).map(sign).join(' / '):'No matching region'));
      check.addEventListener('change',()=>{check.checked?hidden.delete(p.key):hidden.add(p.key);redraw();});focus.addEventListener('click',()=>{selected=p.key;hidden.delete(p.key);check.checked=true;redraw();});return tr;}));redraw();
  }
  function update(state){const chosen=state.project.balls.filter(b=>state.selectedBallIds.includes(b.id));open.disabled=chosen.length<2;count.textContent=chosen.length+' selected · select two or more balls in the gallery.';if(dialog.open){if(chosen.length<2){api.closeDialog(dialog);return;}balls=chosen;guide=state.project.temperatureGuide||{visible:true,start:90,end:270};if(!Comparison.entries(balls).some(p=>p.key===selected))selected=balls[0].id+'/base';fill();}}
  api.on(open,'click',()=>{const state=api.getState();balls=state.project.balls.filter(b=>state.selectedBallIds.includes(b.id));if(balls.length<2)return;hidden=new Set();selected=balls[0].id+'/base';guide=state.project.temperatureGuide||{visible:true,start:90,end:270};shape.value=state.project.pickerShape||'triangle';fill();api.openDialog(dialog);});
  api.on(shape,'change',redraw);api.on(close,'click',()=>api.closeDialog(dialog));api.on(dialog,'cancel',e=>{e.preventDefault();api.closeDialog(dialog);});api.on(dialog,'keydown',e=>{if(e.key==='Escape')api.closeDialog(dialog);});
  api.on(canvas,'click',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*320/r.width,y=(e.clientY-r.top)*320/r.height,hits=points.filter(p=>Math.hypot(x-p.x,y-p.y)<9);if(!hits.length)return;const next=(hits.findIndex(p=>p.key===selected)+1)%hits.length;selected=hits[next].key;redraw();});api.subscribe(update);
}
